<template>
  <fieldset class="materials-area" :disabled="readonly" style="border:0;padding:0;margin:0;min-width:0">
    <section v-for="kind in kinds" :key="kind.type" class="material-section">
      <h3>{{kind.title}} <small>平均单件成本：<em>{{average(kind.type).toFixed(2)}} 元</em></small></h3>
      <div class="material-toolbar"><button class="primary" @click="choose(kind.type)">选择{{kind.label}}</button><button class="warning" @click="newArchive(kind.type)">新增{{kind.type==='fabric'?'主料':'辅料'}}</button><template v-if="kind.type==='accessory'"><button class="primary" @click="saveTemplate()">保存模板</button><button class="primary" @click="chooseTemplate()">选择模板</button></template><button class="primary" @click="addGroup(kind.type)">＋增加使用部位</button><span>物料来自档案，规格与供应商只读</span></div>
      <section v-for="group in groups(kind.type)" :key="group.id" class="material-part-group"><header class="part-group-head"><label>使用部位 <input v-model="group.name" maxlength="500" placeholder="自行命名，如衣身、袖子" @input="syncGroup(group)"/></label><label>本部位统一单件用量 <input type="number" min="0" max="1000000" step="0.001" v-model.number="group.one_use" @input="syncGroup(group)"/> {{group.unit||'按物料单位'}}</label><button @click="choose(kind.type,group.id)">＋添加{{kind.label}}</button><button class="link danger" @click="removeGroup(group)">删除使用部位</button></header><small class="part-group-note">同组所有物料共用此单件用量，可继续增加其他使用部位。空差、损耗等技术资料在样衣中维护。</small><div class="material-scroll"><table class="material-table" :class="kind.type"><thead><tr><th>操作</th><th>序号</th><th v-if="kind.type==='fabric'">类型</th><th v-if="kind.type==='fabric'">物料备注</th><th>{{kind.label}}名称</th><th class="color-description">款色 · <i>颜色/色号</i> · <em>单价</em> · <strong>单件含损耗金额</strong></th><th v-if="kind.type==='accessory'">单位</th><th>成分</th><th v-if="kind.type==='fabric'">规格</th><template v-if="kind.type==='accessory'"><th>使用部位</th><th>克重(g)</th></template><th>供应商名称</th><th v-if="kind.type==='accessory'">物料备注</th></tr></thead>
        <tbody><tr v-for="(m,n) in groupRows(group)" :key="m.key"><td class="material-actions"><button class="link danger" @click="remove(m)">移除</button><button class="link" @click="move(m,-1)">上移</button><button class="link" @click="move(m,1)">下移</button><button class="link" @click="replace(m)">替换物料</button><button class="link" @click="copy(m)">复制物料</button></td><td>{{n+1}}</td><td v-if="kind.type==='fabric'">{{m.role}}</td><td v-if="kind.type==='fabric'"><textarea v-model="m.remark" rows="4" placeholder="请输入备注"/></td><td class="material-name"><input :value="m.name" readonly title="物料名称来自档案，只读"/><small>本单物料照片</small><ImageUpload :disabled="readonly" @uploading="trackFileUpload" v-model="m.order_image_url" size="sm" :title="m.name+' · 本单物料照片'"/><small>支持粘贴，仅保存到本单</small><small>{{m.code}}</small></td>
          <td class="color-description"><div class="material-color-lines"><div v-for="c in visibleColors(m)" :key="c.color"><button class="material-color-text link" @click="editColors(m,c.color)" :title="'编辑'+c.color+'的配色与照片'"><span>{{c.color}}</span> - <i>{{config(m,c.color).color_no||'未填写 / 未填写'}}</i> - <em>{{Number(config(m,c.color).price??m.price).toFixed(2)}}元</em> - <strong>{{unitCost(m,c.color).toFixed(2)}}元</strong></button><button v-if="config(m,c.color).image_url" class="material-color-preview" @click.stop="openImage(config(m,c.color).image_url,m.name+' · '+c.color)" :aria-label="'放大查看'+c.color+'物料照片'" title="点击放大查看"><img :src="config(m,c.color).image_url" :alt="c.color+'物料照片'"/></button></div></div><button class="edit-color" @click="editColors(m)" title="编辑颜色、色号、单价及照片">✎</button></td>
          <td v-if="kind.type==='accessory'"><input :value="m.unit" readonly style="width:70px"/></td><td><textarea v-model="m.ingredient" rows="5" placeholder="本单成分" /></td><td v-if="kind.type==='fabric'" class="material-spec"><label>单位：<input :value="m.unit" readonly/></label><label v-if="kind.type==='fabric'">幅宽：<input :value="m.width" readonly/> cm</label><label>克重：<input :value="m.weight" readonly/> g</label><small>{{m.spec||'未填写其他规格'}}</small></td>
          <template v-if="kind.type==='accessory'"><td>{{m.usage_part||'未命名部位'}}</td><td><input :value="m.weight" readonly style="width:65px"/></td></template><td>{{m.supplier||'档案未设置'}}</td><td v-if="kind.type==='accessory'"><textarea v-model="m.remark" rows="3" placeholder="物料备注"/></td></tr>
          <tr v-if="!groupRows(group).length"><td :colspan="kind.type==='fabric'?9:10" class="empty-material">暂未选择{{kind.label}}，点击上方“选择{{kind.label}}”从物料档案添加</td></tr></tbody></table></div></section>
    </section>
    <details v-if="!hideCrafts" class="craft-requirements"><summary>外发工艺 <small>工艺要求；本厂 / 外发由生产分单确定</small></summary><p><select v-model="selectedCraft"><option value="">选择工序类别</option><option v-for="c in craftTypes" :key="c.id" :value="c.id">{{c.name}}</option></select> <button @click="addCraft()">添加工序</button></p><div v-for="(c,i) in item.crafts" :key="i" class="craft-row"><b>{{c.name}}</b><input v-model="c.instruction" placeholder="工艺要求"/><button class="link danger" @click="item.crafts.splice(i,1)">移除</button></div></details>
    <MaterialPicker :open="picker.open" :type="picker.type" :selected="[]" @close="picker.open=false" @picked="picked" />
    <div v-if="editing" class="entry-dialog-mask"><section class="entry-dialog wide-dialog material-color-dialog" role="dialog" aria-modal="true" aria-label="编辑物料配色与照片" tabindex="-1" ref="colorDialog" @keydown.esc="onEditorEscape"><header class="color-dialog-head"><h3>{{editing.name}} · 配色与照片</h3><button class="color-dialog-close" :disabled="uploadingColors.size>0" aria-label="关闭配色编辑" @click="closeColors()">×</button></header><div class="color-dialog-body"><p>按本单款色填写，颜色和色号不会回写物料档案。单件用量由外层使用部位统一设置，同组物料一致。</p><div class="material-toolbar"><select v-model="addColorway"><option value="">选择新增款色</option><option v-for="c in item.colors.filter(c=>!editing.colors.some(x=>x.colorway===c.color))" :key="c.color" :value="c.color">{{c.color}}</option></select><button @click="addMaterialColor()">＋增加配色</button><small>点击×立即移除该物料配色，外层同步；可重新增加。</small></div><div class="material-scroll"><table class="color-edit-table"><thead><tr><th>款色图片</th><th>款色</th><th>物料颜色</th><th>色号</th><th>单价(元)</th><th>本单配色照片</th></tr></thead><tbody><tr v-for="c in editing.colors" :key="c.colorway" :data-colorway="c.colorway"><td><img v-if="item.color_images[c.colorway]" :src="item.color_images[c.colorway]" style="width:64px;height:64px;object-fit:contain;cursor:zoom-in" @click="openImage(item.color_images[c.colorway],c.colorway)"/><small v-else>暂无款色图片</small></td><td><button class="remove-colorway" :disabled="uploadingColors.has(c.colorway)" :aria-label="'删除'+c.colorway+'配色'" title="删除配色，立即同步外层" @click="removeMaterialColor(c)">×</button> {{c.colorway}}</td><td><input v-model="c.color_name" placeholder="输入物料颜色"/></td><td><input v-model="c.color_no" placeholder="输入色号"/></td><td><input type="number" min="0" step="0.01" v-model.number="c.price" :placeholder="String(editing.price)"/></td><td><ImageUpload :disabled="readonly" v-model="c.image_url" size="lg" @uploading="uploadState(c.colorway,$event)"/><small>上传 / Ctrl+V 粘贴</small></td></tr></tbody></table></div></div><footer class="color-dialog-foot"><template v-if="closingColors"><span>配色或照片尚未保存，如何关闭？</span><button @click="closingColors=false">继续编辑</button><button class="danger" @click="discardColors()">放弃更改</button><button class="primary" @click="saveColors()">保存并关闭</button></template><template v-else><small>{{uploadingColors.size?'图片上传中，请稍候…':'确定后将更新外层配色照片，仅保存到本单。'}}</small><button :disabled="uploadingColors.size>0" @click="closeColors()">取消</button><button class="primary" :disabled="uploadingColors.size>0" @click="saveColors()">确定</button></template></footer></section></div>

  </fieldset>
</template>
<script setup>
import {ref,reactive,computed,onMounted,watch,nextTick} from 'vue';
import {api} from '../api';
import {entryId} from '../utils/orderEntry';
import MaterialPicker from './MaterialPicker.vue';
import ImageUpload from './ImageUpload.vue';
import {openImage,viewer} from '../store/viewer';
const props=defineProps({item:Object,index:Number,readonly:Boolean,hideCrafts:Boolean});
const fileUploads=ref(0);function trackFileUpload(active){fileUploads.value=Math.max(0,fileUploads.value+(active?1:-1));}
defineExpose({busy:()=>fileUploads.value>0||!!editing.value});
const kinds=[{type:'fabric',title:'面料',label:'面料'},{type:'accessory',title:'辅料（拉链、扣子等）',label:'辅料'}];
const picker=reactive({open:false,type:'fabric',replaceKey:null}),editing=ref(null),craftTypes=ref([]),selectedCraft=ref('');
const addColorway=ref(''),colorDialog=ref(null),closingColors=ref(false),uploadingColors=ref(new Set());let originalColors='';
function uploadState(key,busy){const next=new Set(uploadingColors.value);if(busy)next.add(key);else next.delete(key);uploadingColors.value=next;}
function discardColors(){if(uploadingColors.value.size)return;editing.value=null;closingColors.value=false;}
function closeColors(){if(uploadingColors.value.size)return;if(JSON.stringify(editing.value)!==originalColors){closingColors.value=true;return;}discardColors();}
function onEditorEscape(e){if(viewer.open)return;e.preventDefault();e.stopPropagation();closeColors();}

props.item.material_groups ||= [];
const groups=type=>props.item.material_groups.filter(g=>g.type===type);
const groupRows=g=>props.item.materials.filter(m=>m.usage_group_id===g.id);
function addGroup(type){const g={id:entryId(),type,name:'',one_use:0,unit:''};props.item.material_groups.push(g);return g;}
function syncGroup(g){for(const m of groupRows(g)){m.usage_part=g.name;m.one_use=g.one_use;m.split_use=false;for(const c of m.colors||[]){c.qty=null;c.sizes=[];}}}
function removeGroup(g){if(!confirm('确认删除整个使用部位及组内物料、照片、配色资料？'))return;props.item.materials=props.item.materials.filter(m=>m.usage_group_id!==g.id);props.item.material_groups=props.item.material_groups.filter(x=>x.id!==g.id);}
watch(()=>props.item.materials,()=>{for(const m of props.item.materials){if(props.item.material_groups.some(g=>g.id===m.usage_group_id))continue;let g=groups(m.type).find(g=>g.name===(m.usage_part||'')&&Number(g.one_use)===Number(m.one_use||0)&&(!g.unit||g.unit===m.unit));if(!g)g=addGroup(m.type);g.name=m.usage_part||g.name;g.one_use=Number(m.one_use||0);g.unit=m.unit||'';m.usage_group_id=g.id;}},{deep:true,immediate:true});

const sizeNames=computed(()=>props.item.colors[0]?.sizes.map(s=>s.size)||[]);
const rows=type=>props.item.materials.filter(m=>m.type===type);
const visibleColors=m=>props.item.colors.filter(c=>!m.colors_configured||(m.colors||[]).some(x=>x.colorway===c.color));
const config=(m,color)=>m.colors.find(c=>c.colorway===color)||{};
function unitCost(m,color){const c=config(m,color);return Number(c.qty??m.one_use??0)*(1+Number(m.loss||0)/100)*100/Number(m.air_gap||100)*Number(c.price??m.price??0);}
function average(type){const qty=props.item.colors.reduce((n,c)=>n+c.sizes.reduce((a,s)=>a+Number(s.qty||0),0),0);if(!qty)return 0;return rows(type).reduce((n,m)=>n+visibleColors(m).reduce((a,c)=>a+c.sizes.reduce((b,s)=>{const cfg=config(m,c.color),special=cfg.sizes?.find(x=>x.size===s.size);return b+Number(s.qty||0)*Number(special?.one_use??cfg.qty??m.one_use??0)*(1+Number(m.loss||0)/100)*100/Number(m.air_gap||100)*Number(cfg.price??m.price??0);},0),0),0)/qty;}
function choose(type,groupId){const g=groupId?props.item.material_groups.find(g=>g.id===groupId):(groups(type)[0]||addGroup(type));Object.assign(picker,{open:true,type,replaceKey:null,groupId:g.id});}
function newArchive(type){window.open('/materials/new?type='+type,'_blank','noopener');}
function replace(m){Object.assign(picker,{open:true,type:m.type,replaceKey:m.key,groupId:m.usage_group_id});}
function fromArchive(a){return {key:entryId(),material_id:a.id,archive_version:a.version,type:a.type,role:a.type==='fabric'?'主料':'辅料',name:a.name,order_name:a.name,code:a.code,order_image_url:'',unit:a.unit||'',width:a.width||'',weight:a.weight||'',spec:a.spec||'',supplier:a.supplier||'',ingredient:a.composition||'',one_use:0,loss:0,price:0,air_gap:Number(String(a.air_gap||100).replace('%','')),usage_part:'',remark:'',colors:[],split_use:false};}
function picked(archives){if(picker.replaceKey&&archives.length!==1)return alert('替换时请选择一条物料');const g=props.item.material_groups.find(g=>g.id===picker.groupId);if(g&&archives.some(a=>g.unit&&g.unit!==a.unit)||new Set(archives.map(a=>a.unit)).size>1)return alert('同一使用部位的物料单位须一致，请分组添加');const fresh=archives.map(a=>({...fromArchive(a),usage_group_id:g.id,usage_part:g.name,one_use:g.one_use}));if(fresh.length)g.unit=fresh[0].unit;if(picker.replaceKey){const i=props.item.materials.findIndex(m=>m.key===picker.replaceKey);props.item.materials.splice(i,1,...fresh);}else props.item.materials.push(...fresh);picker.open=false;}
function remove(m){props.item.materials.splice(props.item.materials.indexOf(m),1);}
function copy(m){const c=JSON.parse(JSON.stringify(m));c.key=entryId();props.item.materials.splice(props.item.materials.indexOf(m)+1,0,c);}
function move(m,delta){const i=props.item.materials.indexOf(m),target=props.item.materials.map((x,n)=>({x,n})).filter(y=>y.x.type===m.type),j=target.findIndex(y=>y.n===i)+delta;if(j<0||j>=target.length)return;const k=target[j].n;[props.item.materials[i],props.item.materials[k]]=[props.item.materials[k],props.item.materials[i]];}
function editColors(m,color){closingColors.value=false;uploadingColors.value=new Set();addColorway.value='';editing.value=JSON.parse(JSON.stringify(m));editing.value.colors=props.item.colors.filter(c=>!m.colors_configured||m.colors.some(x=>x.colorway===c.color)).map(c=>{const cfg=config(m,c.color);return {...cfg,colorway:c.color,color_name:(cfg.color_no||'').includes(' / ')?cfg.color_no.split(' / ')[0]:'',color_no:(cfg.color_no||'').includes(' / ')?cfg.color_no.split(' / ').slice(1).join(' / '):(cfg.color_no||''),price:cfg.price??null,qty:cfg.qty??null,image_url:cfg.image_url||'',size_values:Object.fromEntries((cfg.sizes||[]).map(s=>[s.size,s.one_use]))};});originalColors=JSON.stringify(editing.value);nextTick(()=>{colorDialog.value?.focus();if(color){const row=Array.from(colorDialog.value?.querySelectorAll('[data-colorway]')||[]).find(r=>r.dataset.colorway===color);row?.scrollIntoView({block:'nearest'});row?.querySelector('input')?.focus({preventScroll:true});}});}
function addMaterialColor(){if(!addColorway.value)return alert('请选择款色');editing.value.colors.push({colorway:addColorway.value,color_name:'',color_no:'',price:null,qty:null,image_url:'',size_values:{}});addColorway.value='';}
function removeMaterialColor(c){
 if(uploadingColors.value.has(c.colorway))return;
 const draft=editing.value,m=props.item.materials.find(x=>x.key===draft.key);
 draft.colors=draft.colors.filter(x=>x.colorway!==c.colorway);draft.colors_configured=true;
 // 删除立即提交到本单物料；其他尚未保存的编辑仍留在弹窗里。
 m.colors=draft.colors.map(x=>({...config(m,x.colorway),colorway:x.colorway}));m.colors_configured=true;
 const baseline=JSON.parse(originalColors);baseline.colors=baseline.colors.filter(x=>x.colorway!==c.colorway);baseline.colors_configured=true;originalColors=JSON.stringify(baseline);
}

function saveColors(){if(uploadingColors.value.size)return;const draft=editing.value;for(const c of draft.colors){c.qty=null;c.sizes=[];c.color_no=[c.color_name?.trim(),c.color_no?.trim()].filter(Boolean).join(' / ');delete c.color_name;delete c.size_values;if(c.price==='')c.price=null;if(c.qty==='')c.qty=null;}const m=props.item.materials.find(x=>x.key===draft.key);m.colors=draft.colors;m.colors_configured=true;editing.value=null;}
async function saveTemplate(){const name=prompt('辅料模板名称');if(!name?.trim())return;try{await api.saveOrderMaterialTemplate({name:name.trim(),materials:rows('accessory').map(m=>({material_id:m.material_id,one_use:m.one_use,loss:m.loss,price:m.price,usage_part:m.usage_part}))});alert('辅料模板已保存');}catch(e){alert(e.message);}}
async function chooseTemplate(){try{const ts=await api.orderMaterialTemplates();if(!ts.length)return alert('暂无辅料模板');const name=prompt('填写模板名称：\n'+ts.map(t=>t.name).join('\n'));const t=ts.find(t=>t.name===name);if(!t)return;const archives=await api.materials({type:'accessory'});for(const saved of t.materials){const a=archives.find(a=>a.id===saved.material_id&&a.status==='active');if(!a)throw new Error('模板中物料已停用或删除，请重新配置');}props.item.materials.push(...t.materials.map(s=>({...fromArchive(archives.find(a=>a.id===s.material_id)),...s})));}catch(e){alert(e.message);}}
function addCraft(){const c=craftTypes.value.find(x=>x.id===selectedCraft.value);if(c)props.item.crafts.push({craft_type_id:c.id,name:c.name,instruction:''});}
onMounted(async()=>{try{craftTypes.value=await api.craftTypes({status:'active'});}catch{}});
</script>
